export const s12EntrepreneurshipHi: Record<string, { stem: string; options: string[]; explanation: string }> = {
  "s12ent-b-001": { stem: "'उद्यमी' (Entrepreneur) शब्द जिस फ्रांसीसी क्रिया से बना है, उसका अर्थ है:", options: ["नवप्रवर्तन करना", "उपक्रम करना (कार्य का बीड़ा उठाना)", "व्यापार करना", "निवेश करना"], explanation: "'Entrepreneur' फ्रांसीसी शब्द 'entreprendre' से बना है, जिसका अर्थ है उपक्रम करना या कार्य का बीड़ा उठाना। नवप्रवर्तन तो उद्यमी की भूमिका की शुम्पीटर द्वारा दी गई बाद की व्याख्या है, शब्द का शाब्दिक अर्थ नहीं।" },
  "s12ent-b-002": { stem: "18वीं शताब्दी के वह अर्थशास्त्री, जिन्होंने उद्यमी को ऐसा व्यक्ति बताया जो साधन-सेवाएँ निश्चित कीमतों पर खरीदता है और उत्पाद अनिश्चित कीमतों पर बेचता है और इस प्रकार जोखिम वहन करता है, थे:", options: ["रिचर्ड कैंटिलॉन", "एडम स्मिथ", "जे.बी. से", "अल्फ्रेड मार्शल"], explanation: "रिचर्ड कैंटिलॉन अर्थशास्त्र में इस शब्द का प्रयोग करने वाले आरंभिक विद्वानों में थे। उन्होंने उद्यमी को निश्चित लागत और अनिश्चित विक्रय मूल्य के बीच काम करने वाला जोखिम वाहक माना।" },
  "s12ent-b-003": { stem: "क्लेरेंस डैनहॉफ के वर्गीकरण में, वे उद्यमी जो अत्यंत सतर्क और संशयी होते हैं तथा परिवर्तन को तभी अपनाते हैं जब ऐसा न करने से स्पष्ट रूप से हानि हो, कहलाते हैं:", options: ["नवप्रवर्तक उद्यमी", "फेबियन उद्यमी", "अनुकरणशील उद्यमी", "ड्रोन (निष्क्रिय) उद्यमी"], explanation: "फेबियन उद्यमी सतर्क होते हैं और धीरे बदलते हैं; वे नई विधियाँ तभी अपनाते हैं जब हानि का स्पष्ट खतरा हो। ड्रोन उद्यमी तो हानि होने पर भी परिवर्तन से इनकार करते हैं।" },
  "s12ent-b-004": { stem: "डैनहॉफ के अनुसार, वे उद्यमी जो उत्पादन की विधियों में परिवर्तन के अवसरों को अपनाने से इनकार करते हैं, भले ही इससे उनका प्रतिफल घट जाए, कहलाते हैं:", options: ["फेबियन उद्यमी", "ड्रोन (निष्क्रिय) उद्यमी", "अनुकरणशील उद्यमी", "नवप्रवर्तक उद्यमी"], explanation: "ड्रोन उद्यमी परंपरागत विधियों से चिपके रहते हैं और लाभ घटने पर भी परिवर्तन का विरोध करते हैं; अंततः वे बाज़ार से बाहर हो सकते हैं।" },
  "s12ent-b-005": { stem: "'अंतःउद्यमी' (इंट्राप्रेन्योर) का सर्वोत्तम वर्णन है:", options: ["एक कर्मचारी जो किसी विद्यमान संगठन के भीतर उद्यमशील भावना से नए उपक्रम विकसित करता और आगे बढ़ाता है", "एक व्यक्ति जो विरासत में मिली पारिवारिक पूँजी से व्यवसाय आरंभ करता है", "एक निवेशक जो इक्विटी के बदले स्टार्ट-अप को वित्त देता है", "एक उद्यमी जो केवल अंतरराष्ट्रीय बाज़ारों में कार्य करता है"], explanation: "अंतःउद्यमी किसी विद्यमान फर्म के भीतर संगठन के संसाधनों का उपयोग करके नवप्रवर्तन करता है; अधिकांश वित्तीय जोखिम व्यक्ति नहीं, बल्कि फर्म वहन करती है।" },
  "s12ent-b-006": { stem: "डेविड मैक्लीलैंड के अनुसार, उद्यमशील व्यवहार से सबसे अधिक जुड़ी आवश्यकता है:", options: ["शक्ति की आवश्यकता (nPow)", "उपलब्धि की आवश्यकता (nAch)", "संबद्धता की आवश्यकता (nAff)", "सुरक्षा की आवश्यकता"], explanation: "मैक्लीलैंड (The Achieving Society, 1961) के अनुसार उपलब्धि की उच्च आवश्यकता व्यक्ति को चुनौतीपूर्ण लक्ष्य तय करने और व्यक्तिगत उत्तरदायित्व लेने को प्रेरित करती है, जो उद्यमियों की विशेषता है।" },
  "s12ent-b-007": { stem: "जोसेफ शुम्पीटर ने उद्यमी को मुख्यतः माना:", options: ["बीमा योग्य जोखिम का वाहक", "पूँजीपति, जो धन उपलब्ध कराता है", "नियमित कार्यों का प्रबंधक", "नवप्रवर्तक, जो नए संयोजन लागू करता है"], explanation: "शुम्पीटर के लिए उद्यमिता का सार नवप्रवर्तन है, अर्थात 'नए संयोजन' लागू करना। उनके मत में जोखिम वहन पूँजीपति करता है, उद्यमी के रूप में उद्यमी नहीं।" },
  "s12ent-b-008": { stem: "निम्नलिखित में से कौन-सा शुम्पीटर द्वारा बताए गए नवप्रवर्तन (नए संयोजन) के पाँच रूपों में से एक नहीं है?", options: ["नई वस्तु या वस्तु की नई गुणवत्ता का प्रवेश", "नए बाज़ार का खुलना", "कच्चे माल की आपूर्ति के नए स्रोत की प्राप्ति", "श्रमिकों को दी जाने वाली मज़दूरी बढ़ाना"], explanation: "शुम्पीटर के पाँच रूप हैं: नई वस्तु, उत्पादन की नई विधि, नया बाज़ार, कच्चे माल या अर्ध-निर्मित वस्तुओं की आपूर्ति का नया स्रोत, और उद्योग का नया संगठन। मज़दूरी बढ़ाना नवप्रवर्तन नहीं है।" },
  "s12ent-b-009": { stem: "'उद्यमी जन्म से होते हैं, बनाए नहीं जाते' एक सामान्य भ्रांति है। कौन-सा कथन वास्तविकता दर्शाता है?", options: ["केवल व्यावसायिक परिवारों के बच्चे ही सफल उद्यमी बन सकते हैं", "उद्यमशील योग्यता जन्म से निश्चित होती है और बदल नहीं सकती", "औपचारिक प्रशिक्षण व्यक्ति की उद्यमशील योग्यता घटाता है", "उद्यमशील दक्षताएँ प्रशिक्षण, शिक्षा और अनुभव से विकसित की जा सकती हैं"], explanation: "उद्यमिता विकास कार्यक्रमों (उपलब्धि प्रेरणा प्रशिक्षण सहित) के अनुभव बताते हैं कि उद्यमशील गुण और कौशल सीखे और सुदृढ़ किए जा सकते हैं।" },
  "s12ent-b-010": { stem: "मैक्लीलैंड के अनुसार, उपलब्धि की उच्च आवश्यकता वाले व्यक्ति सामान्यतः पसंद करते हैं:", options: ["मध्यम, सोचे-समझे (परिकलित) जोखिम", "अत्यधिक, जुए जैसे जोखिम", "ऐसी स्थितियाँ जिनमें कोई जोखिम न हो", "ऐसे परिणाम जो पूर्णतः भाग्य पर निर्भर हों"], explanation: "उच्च उपलब्धि वाले व्यक्ति मध्यम कठिनाई वाले लक्ष्य चुनते हैं जहाँ सफलता संभव हो और उनके अपने प्रयास पर निर्भर हो; केवल भाग्य वाले या अत्यंत सुरक्षित कार्य उपलब्धि का भाव नहीं देते।" },
  "s12ent-b-011": { stem: "जब उद्यमी औद्योगिक रूप से पिछड़े क्षेत्रों में उद्यम स्थापित करते हैं, तो आर्थिक विकास में सबसे प्रत्यक्ष योगदान होता है:", options: ["आर्थिक शक्ति का अधिक केंद्रीकरण", "संतुलित क्षेत्रीय विकास", "आयात में वृद्धि", "शहरी भीड़भाड़ में वृद्धि"], explanation: "पिछड़े क्षेत्रों में उद्यमों के फैलाव से रोज़गार और आय का प्रसार होता है, जिससे क्षेत्रीय असमानताएँ घटती हैं।" },
  "s12ent-b-012": { stem: "फ्रांसीसी अर्थशास्त्री जे.बी. से ने उद्यमी को मुख्यतः ऐसा व्यक्ति बताया जो:", options: ["व्यवसाय को केवल पूँजी उपलब्ध कराता है", "ऐसी अनिश्चितता वहन करता है जिसका बीमा नहीं हो सकता", "उत्पादन के साधनों को संयोजित और समन्वित करता है", "ऐसे नए संयोजन लाता है जो संतुलन को भंग करते हैं"], explanation: "जे.बी. से ने उद्यमी को भूमि, श्रम और पूँजी को एक साथ लाने वाला संगठनकर्ता माना। अनिश्चितता वहन नाइट का और नए संयोजन शुम्पीटर का विचार है।" },
  "s12ent-b-013": { stem: "फ्रैंक एच. नाइट ने उद्यमशील लाभ को किसके वहन से जोड़ा?", options: ["आग और चोरी जैसे बीमा योग्य जोखिम", "नियमित प्रबंधन की मज़दूरी", "अनिश्चितता, जिसे न मापा जा सकता है न बीमा किया जा सकता है", "उधार ली गई पूँजी पर ब्याज"], explanation: "'Risk, Uncertainty and Profit' (1921) में नाइट ने मापने योग्य (बीमा योग्य) जोखिम और वास्तविक अनिश्चितता में अंतर किया; लाभ बीमा न हो सकने वाली अनिश्चितता वहन करने का पुरस्कार है।" },
  "s12ent-b-014": { stem: "कौन-सी विशेषता एक उद्यमी को वेतनभोगी प्रबंधक से अलग करती है?", options: ["उद्यमी को निश्चित मासिक वेतन मिलता है", "उद्यमी किसी वरिष्ठ के निर्देशन में कार्य करता है", "निर्णय लेने में उद्यमी की कोई भूमिका नहीं होती", "उद्यमी उद्यम का जोखिम और अनिश्चितता वहन करता है"], explanation: "प्रबंधक वेतन पाने वाला कर्मचारी है; उद्यमी उपक्रम के अनिश्चित प्रतिफल का स्वामी होता है और उसका जोखिम वहन करता है।" },
  "s12ent-b-015": { stem: "डैनहॉफ के अनुसार, कौन-सा उद्यमी, जो अन्यत्र सफल सिद्ध हो चुके नवप्रवर्तनों की नकल करके उन्हें अपनाता है, विकासशील अर्थव्यवस्थाओं के लिए विशेष रूप से उपयुक्त है?", options: ["नवप्रवर्तक उद्यमी", "फेबियन उद्यमी", "ड्रोन (निष्क्रिय) उद्यमी", "अनुकरणशील (अंगीकारी) उद्यमी"], explanation: "अनुकरणशील उद्यमी नवप्रवर्तकों द्वारा विकसित सफल तकनीकें अपनाते हैं; विकासशील देशों में इससे मौलिक शोध की लागत के बिना तकनीक तेज़ी से फैलती है।" },
  "s12ent-b-016": { stem: "निम्नलिखित में से कौन-सी एक उद्यमशील दक्षता है?", options: ["असफलता का ऐसा भय जो कार्य करने से रोके", "प्रत्येक निर्णय के लिए दूसरों पर निर्भरता", "बाज़ार संबंधी जानकारी से बचना", "बाधाओं के बावजूद दृढ़ता (लगन)"], explanation: "दृढ़ता (बाधाएँ पार करने के लिए बार-बार प्रयास करना) प्रमुख उद्यमशील दक्षताओं में से एक है; अन्य विकल्प उद्यमशील व्यवहार को कमज़ोर करते हैं।" },
  "s12ent-b-017": { stem: "पीटर ड्रकर के अनुसार, उद्यमी सदैव परिवर्तन की खोज करता है, उसके प्रति प्रतिक्रिया करता है और उसका उपयोग करता है:", options: ["टाले जाने योग्य खतरे के रूप में", "अपरिहार्य लागत के रूप में", "एक अवसर के रूप में", "कानूनी दायित्व के रूप में"], explanation: "'Innovation and Entrepreneurship' (1985) में ड्रकर ने परिवर्तन को अवसर का स्रोत बताया, जिसका उद्यमी नवप्रवर्तन द्वारा व्यवस्थित रूप से उपयोग करते हैं।" },
  "s12ent-b-018": { stem: "बिना किसी पारिवारिक व्यावसायिक पृष्ठभूमि के स्वयं उद्यम आरंभ करने वाला व्यक्ति कहलाता है:", options: ["वंशानुगत उद्यमी", "अंतःउद्यमी", "प्रथम पीढ़ी का उद्यमी", "ड्रोन (निष्क्रिय) उद्यमी"], explanation: "प्रथम पीढ़ी के उद्यमी अपने परिवार में व्यवसाय आरंभ करने वाले पहले व्यक्ति होते हैं; वंशानुगत उद्यमी पारिवारिक उद्यम संभालते हैं।" },
  "s12ent-p-001": { stem: "विचारकों का उद्यमी संबंधी उनके दृष्टिकोण से मिलान कीजिए:\nA. रिचर्ड कैंटिलॉन\nB. जोसेफ शुम्पीटर\nC. जे.बी. से\nD. डेविड मैक्लीलैंड\n1. उपलब्धि की आवश्यकता\n2. निश्चित लागत और अनिश्चित कीमत के बीच जोखिम वाहक\n3. नए संयोजन लागू करने वाला नवप्रवर्तक\n4. उत्पादन के साधनों का समन्वयक", options: ["A-3, B-2, C-1, D-4", "A-2, B-3, C-4, D-1", "A-4, B-3, C-2, D-1", "A-2, B-4, C-3, D-1"], explanation: "कैंटिलॉन: जोखिम वहन; शुम्पीटर: नवप्रवर्तन; से: साधनों का समन्वय; मैक्लीलैंड: उपलब्धि की आवश्यकता।" },
  "s12ent-p-002": { stem: "अभिकथन (A): मैक्लीलैंड के अनुसार, उपलब्धि की उच्च आवश्यकता वाले व्यक्ति मध्यम कठिनाई वाले कार्य पसंद करते हैं।\nकारण (R): ऐसे कार्यों में सफलता की वास्तविक संभावना रहती है और सफलता व्यक्ति के अपने प्रयास तथा योग्यता को दर्शाती है।", options: ["A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "अत्यंत सरल कार्य उपलब्धि का भाव नहीं देते और अत्यंत कठिन कार्य भाग्य पर निर्भर होते हैं; मध्यम कार्यों में सफलता स्वयं अर्जित लगती है, अतः R, A की सही व्याख्या है।" },
  "s12ent-p-003": { stem: "शुम्पीटर के नवप्रवर्तन सिद्धांत के अनुसार निम्नलिखित में से कौन-सा कथन सही है?", options: ["उद्यमी को वित्तीय जोखिम वहन करने वाला पूँजीपति भी होना चाहिए", "नवप्रवर्तन और आविष्कार का अर्थ एक ही है", "उद्यमी आर्थिक जीवन के चक्रीय प्रवाह को संतुलन में बनाए रखते हैं", "व्यक्ति तभी तक उद्यमी है जब तक वह नए संयोजन लागू करता है; व्यवसाय को नियमित ढंग से चलाने लगने पर वह उद्यमी नहीं रहता"], explanation: "शुम्पीटर के अनुसार उद्यमिता एक कार्य है, स्थायी पद नहीं; नियमित प्रबंधन उद्यमिता नहीं है। उन्होंने नवप्रवर्तन को आविष्कार से अलग माना, जोखिम पूँजीपति पर डाला और उद्यमी को चक्रीय प्रवाह भंग करने वाला माना।" },
  "s12ent-p-004": { stem: "भारत में 'काकीनाडा प्रयोग' संबंधित है:", options: ["व्यापार चक्रों पर शुम्पीटर के अध्ययन से", "भारत के पहले उद्यम पूँजी कोष से", "कृषि उद्यमियों पर डैनहॉफ के अध्ययन से", "मैक्लीलैंड के कार्य पर आधारित उद्यमियों के उपलब्धि प्रेरणा प्रशिक्षण से"], explanation: "1960 के दशक में मैक्लीलैंड और सहयोगियों ने काकीनाडा (आंध्र प्रदेश) के व्यवसायियों को उपलब्धि प्रेरणा प्रशिक्षण दिया और प्रशिक्षित प्रतिभागियों में अधिक उद्यमशील गतिविधि पाई।" },
  "s12ent-p-005": { stem: "अंतःउद्यमियों के बारे में कथनों पर विचार कीजिए:\nI. अंतःउद्यमी किसी विद्यमान संगठन के भीतर कार्य करता है।\nII. अंतःउद्यमी नए उपक्रम का पूरा वित्तीय जोखिम व्यक्तिगत रूप से वहन करता है।\nIII. इस शब्द को गिफ़र्ड पिंचॉट ने लोकप्रिय बनाया।\nइनमें से कौन-से सही हैं?", options: ["केवल I और II", "केवल II और III", "केवल I और III", "I, II और III"], explanation: "अंतःउद्यमी ऐसी फर्म के भीतर काम करता है जो उपक्रम को वित्त देती है और अधिकांश वित्तीय जोखिम उठाती है, अतः II गलत है। गिफ़र्ड पिंचॉट ने यह शब्द लोकप्रिय बनाया (Intrapreneuring, 1985)।" },
  "s12ent-p-006": { stem: "क्लेरेंस डैनहॉफ के उद्यमी वर्गीकरण के संदर्भ में बेमेल को चुनिए:", options: ["औद्योगिक", "नवप्रवर्तक", "अनुकरणशील", "फेबियन"], explanation: "डैनहॉफ के चार प्रकार नवप्रवर्तक, अनुकरणशील, फेबियन और ड्रोन हैं, जो नवप्रवर्तन अपनाने की तत्परता पर आधारित हैं। 'औद्योगिक' व्यवसाय के प्रकार पर आधारित वर्गीकरण है।" },
  "s12ent-p-007": { stem: "वह सिद्धांत जो उद्यमिता के विकास को प्रोटेस्टेंट कार्य-नीति जैसे धार्मिक विश्वासों और मूल्यों का परिणाम बताता है, संबंधित है:", options: ["एवरेट हेगन से", "मैक्स वेबर से", "हार्वे लीबेंस्टीन से", "फ्रैंक नाइट से"], explanation: "मैक्स वेबर (The Protestant Ethic and the Spirit of Capitalism) ने परिश्रम और मितव्ययिता को प्रोत्साहित करने वाले धार्मिक मूल्यों को पूँजीवादी उद्यम के उदय से जोड़ा; यह उद्यमिता का समाजशास्त्रीय सिद्धांत है।" },
  "s12ent-p-008": { stem: "एवरेट हेगन का सिद्धांत उद्यमियों के उदय का मुख्य कारण मानता है:", options: ["सस्ते बैंक ऋण की उपलब्धता", "केवल प्रशिक्षण से अर्जित उच्च उपलब्धि प्रेरणा", "बीमा न हो सकने वाली अनिश्चितता का वहन", "किसी सामाजिक समूह से प्रतिष्ठा-सम्मान का छिन जाना"], explanation: "हेगन के अनुसार जब किसी समूह की परंपरागत सामाजिक प्रतिष्ठा छिन जाती है, तो उसके सदस्य पीढ़ियों में सम्मान पुनः पाने हेतु नवप्रवर्तक आर्थिक गतिविधि की ओर मुड़ सकते हैं।" },
  "s12ent-p-009": { stem: "हार्वे लीबेंस्टीन ने उद्यमी की किस भूमिका पर बल दिया?", options: ["नए उत्पादों द्वारा रचनात्मक विनाश लाना", "अपूर्ण बाज़ारों में अंतराल भरना और आगतों की पूर्ति करना", "पूर्ण प्रतिस्पर्धी बाज़ारों में साधनों का समन्वय करना", "संबद्धता की आवश्यकता को संतुष्ट करना"], explanation: "लीबेंस्टीन ने उद्यमी को ऐसा व्यक्ति माना जो अपूर्ण बाज़ारों में अंतराल भरता और अनुपलब्ध आगतों की पूर्ति करता है, जिससे अकुशलता घटती है।" },
  "s12ent-p-010": { stem: "अभिकथन (A): उद्यमिता केवल नई, बड़ी विनिर्माण फर्में आरंभ करने तक सीमित है।\nकारण (R): उद्यमशील व्यवहार छोटे व्यवसायों, सेवा उपक्रमों, सामाजिक उद्यमों और विद्यमान फर्मों के भीतर भी दिखता है।", options: ["A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "A एक भ्रांति है: उद्यमिता किसी भी क्षेत्र और किसी भी पैमाने पर अवसर पहचानकर उन पर कार्य करने से संबंधित है। R सत्य है।" },
  "s12ent-p-011": { stem: "शुम्पीटर की योजना में 'उद्योग के नए संगठन' प्रकार के नवप्रवर्तन का उदाहरण कौन-सा है?", options: ["किसी विद्यमान पेय का नया स्वाद आरंभ करना", "किसी विद्यमान उत्पाद का नए देश को निर्यात करना", "प्रतिद्वंद्वी फर्मों के विलय से एकाधिकार की स्थिति बनाना", "नए खोजे गए आपूर्तिकर्ता से कच्चा माल लेना"], explanation: "शुम्पीटर का पाँचवाँ रूप एकाधिकार की स्थिति बनाना (या उसे तोड़ना) है। अन्य विकल्प क्रमशः नई वस्तु, नया बाज़ार और आपूर्ति का नया स्रोत हैं।" },
  "s12ent-p-012": { stem: "आर्थिक विकास में उद्यमियों की भूमिका के बारे में निम्नलिखित में से कौन-से कथन सही हैं?\nI. वे निष्क्रिय बचत को उत्पादक पूँजी में बदलते हैं।\nII. वे निर्यात बढ़ाकर विदेशी मुद्रा अर्जित कर सकते हैं।\nIII. वे अनिवार्य रूप से आर्थिक शक्ति का केंद्रीकरण बढ़ाते हैं।", options: ["केवल I", "केवल II और III", "केवल I और II", "I, II और III"], explanation: "उद्यमी पूँजी निर्माण और निर्यात संवर्धन में सहायक होते हैं। उद्यमियों की अधिक संख्या वास्तव में आर्थिक शक्ति के केंद्रीकरण को घटाती है, बढ़ाती नहीं।" },
  "s12ent-p-013": { stem: "एक व्यक्ति जो नौकरी छूटने पर और कोई रोज़गार न मिलने पर छोटा व्यवसाय आरंभ करता है, मुख्यतः किससे प्रेरित है?", options: ["धकेलने वाला (विवशकारी) कारक", "खींचने वाला (आकर्षक) कारक", "स्वास्थ्य (हाइजीन) कारक", "संबद्धता की आवश्यकता"], explanation: "धकेलने वाले कारक प्रतिकूल परिस्थितियाँ (बेरोज़गारी, नौकरी से असंतोष) हैं जो व्यक्ति को उद्यमिता की ओर विवश करती हैं; खींचने वाले कारक पहचाना गया अवसर या स्वतंत्रता की इच्छा जैसे आकर्षण हैं।" },
  "s12ent-p-014": { stem: "निम्नलिखित में से कौन-सा व्यवहार उद्यमशील दक्षता को दर्शाने के बजाय कमज़ोर करेगा?", options: ["अपने कार्य-निष्पादन पर प्रतिपुष्टि (फीडबैक) माँगना", "व्यवस्थित योजना और निगरानी", "प्रतिस्पर्धियों और ग्राहकों संबंधी जानकारी से बचना", "बाधाओं को पार करने में दृढ़ता"], explanation: "जानकारी खोजना स्वयं एक प्रमुख दक्षता है; जानकारी से बचने से गलत निर्णय होते हैं। प्रतिपुष्टि माँगना, व्यवस्थित योजना और दृढ़ता मान्य दक्षताएँ हैं।" },
  "s12ent-p-015": { stem: "सामाजिक उद्यमी के बारे में कौन-सा कथन सही है?", options: ["मुख्य उद्देश्य शेयरधारकों को अधिकतम लाभांश देना है", "सामाजिक उद्यमी केवल सरकारी विभाग के रूप में कार्य कर सकता है", "मुख्य उद्देश्य सामाजिक या पर्यावरणीय प्रभाव है, और अधिशेष का अधिकांश भाग उद्देश्य में पुनर्निवेश किया जाता है", "सामाजिक उद्यमी अपनी गतिविधियों से कभी कोई आय अर्जित नहीं करते"], explanation: "सामाजिक उद्यमी सामाजिक समस्याएँ सुलझाने के लिए उद्यम पद्धतियों का उपयोग करते हैं; वे आय अर्जित कर सकते हैं, पर सफलता मुख्यतः सामाजिक प्रभाव से मापते हैं।" },
  "s12ent-p-016": { stem: "क्लेरेंस डैनहॉफ ने उद्यमियों का वर्गीकरण किस आधार पर किया?", options: ["व्यावसायिक स्वामित्व का प्रारूप", "व्यावसायिक गतिविधि का प्रकार", "स्थान, शहरी या ग्रामीण", "नवप्रवर्तन अपनाने के प्रति उनकी तत्परता और दृष्टिकोण"], explanation: "डैनहॉफ के चार प्रकार (नवप्रवर्तक, अनुकरणशील, फेबियन, ड्रोन) दर्शाते हैं कि उद्यमी कितनी तत्परता से नवप्रवर्तन आरंभ करते या अपनाते हैं।" },
  "s12ent-p-017": { stem: "शुम्पीटर का 'रचनात्मक विनाश' (creative destruction) पद उनकी किस पुस्तक से लोकप्रिय हुआ?", options: ["Capitalism, Socialism and Democracy", "The Theory of Economic Development", "The Achieving Society", "Risk, Uncertainty and Profit"], explanation: "शुम्पीटर ने रचनात्मक विनाश का वर्णन Capitalism, Socialism and Democracy (1942) में किया। The Achieving Society मैक्लीलैंड की और Risk, Uncertainty and Profit नाइट की पुस्तक है।" },
  "s12ent-b-019": { stem: "SWOT विश्लेषण में कौन-से दो तत्व फर्म के आंतरिक पर्यावरण से संबंधित हैं?", options: ["शक्तियाँ और अवसर", "शक्तियाँ और कमज़ोरियाँ", "अवसर और खतरे", "कमज़ोरियाँ और खतरे"], explanation: "शक्तियाँ और कमज़ोरियाँ आंतरिक और काफ़ी हद तक नियंत्रणीय हैं; अवसर और खतरे बाहरी पर्यावरण से उत्पन्न होते हैं।" },
  "s12ent-b-020": { stem: "उत्पाद जीवन चक्र में, वह अवस्था जिसमें बिक्री शिखर पर पहुँचती है और प्रतिस्पर्धा सबसे तीव्र होती है:", options: ["प्रवेश (परिचय)", "परिपक्वता", "वृद्धि", "पतन (ह्रास)"], explanation: "परिपक्वता में बिक्री की वृद्धि शिखर पर स्थिर हो जाती है, बाज़ार संतृप्त होता है और अनेक प्रतिस्पर्धी हिस्सेदारी के लिए संघर्ष करते हैं।" },
  "s12ent-b-021": { stem: "व्यवसाय योजना का वह भाग जो सामान्यतः सबसे अंत में लिखा जाता है परंतु सबसे आरंभ में रखा जाता है:", options: ["वित्तीय योजना", "कार्यकारी सारांश", "संचालन योजना", "परिशिष्ट"], explanation: "कार्यकारी सारांश पूरी योजना का संक्षेप है, अतः अन्य भागों के बाद ही लिखा जा सकता है, फिर भी यह पहले आता है क्योंकि निवेशक जैसे पाठक इसे सबसे पहले देखते हैं।" },
  "s12ent-b-022": { stem: "विचार-सृजन अवस्था में विचार-मंथन (ब्रेनस्टॉर्मिंग) का मूल नियम है:", options: ["प्रत्येक विचार का सुझाव आते ही मूल्यांकन होना चाहिए", "केवल विशेषज्ञ ही विचार सुझा सकते हैं", "विचार कई दौरों में लिखित रूप से गुमनाम भेजे जाने चाहिए", "विचारों की कोई आलोचना नहीं; अधिक संख्या और मुक्त विचार को प्रोत्साहन"], explanation: "विचार-मंथन सृजन को मूल्यांकन से अलग रखता है ताकि लोग एक-दूसरे के विचारों पर आगे बढ़ सकें। गुमनाम लिखित दौर डेल्फ़ी तकनीक की विशेषता है।" },
  "s12ent-b-023": { stem: "बाज़ार अनुसंधान में निम्नलिखित में से कौन-सा प्राथमिक आँकड़ों का स्रोत है?", options: ["फर्म द्वारा लक्षित ग्राहकों का प्रश्नावली सर्वेक्षण", "जनगणना रिपोर्टें", "व्यापार पत्रिकाओं के लेख", "प्रतिस्पर्धियों की प्रकाशित वार्षिक रिपोर्टें"], explanation: "प्राथमिक आँकड़े किसी विशेष उद्देश्य हेतु स्वयं पहली बार एकत्र किए जाते हैं। जनगणना रिपोर्ट, पत्रिकाएँ और प्रकाशित रिपोर्टें द्वितीयक आँकड़े हैं।" },
  "s12ent-b-024": { stem: "किसी परियोजना की तकनीकी साध्यता मुख्यतः किसकी जाँच करती है?", options: ["निवेश पर अपेक्षित प्रतिफल दर", "उत्पाद की संभावित माँग", "उपयुक्त तकनीक, मशीनरी, कच्चे माल और उत्पादन प्रक्रिया की उपलब्धता", "स्वामी के प्रति कर्मचारियों का दृष्टिकोण"], explanation: "तकनीकी साध्यता यह देखती है कि उपलब्ध तकनीक और आगतों से उत्पाद बनाया जा सकता है या नहीं। प्रतिफल वित्तीय साध्यता और माँग बाज़ार साध्यता का विषय है।" },
  "s12ent-b-025": { stem: "पर्यावरण अवलोकन हेतु प्रयुक्त PESTLE विश्लेषण में अक्षर 'L' का अर्थ है:", options: ["कानूनी (Legal)", "श्रम (Labour)", "स्थान (Location)", "संभार तंत्र (Logistics)"], explanation: "PESTLE में वृहद पर्यावरण के राजनीतिक, आर्थिक, सामाजिक, तकनीकी, कानूनी और पर्यावरणीय कारक आते हैं।" },
  "s12ent-b-026": { stem: "उत्पाद जीवन चक्र की वह अवस्था जिसमें बिक्री कम होती है, लाभ सामान्यतः ऋणात्मक होता है और संवर्धन का मुख्य उद्देश्य जागरूकता पैदा करना होता है:", options: ["वृद्धि", "प्रवेश (परिचय)", "परिपक्वता", "पतन (ह्रास)"], explanation: "प्रवेश अवस्था में प्रारंभिक और संवर्धन लागत अधिक, मात्रा कम और खरीदार कम होने से प्रायः हानि होती है।" },
  "s12ent-b-027": { stem: "वितरण माध्यम (थोक और खुदरा विक्रेता) नए व्यावसायिक विचारों के उपयोगी स्रोत मुख्यतः इसलिए हैं क्योंकि:", options: ["वे नए उपक्रमों को कम ब्याज पर वित्त देते हैं", "वे नए उत्पादों के पेटेंट प्रदान करते हैं", "वे सरकारी जनगणना करते हैं", "वे बाज़ार के निकट होते हैं और जानते हैं कि ग्राहक क्या माँगते हैं"], explanation: "माध्यम के सदस्य प्रतिदिन ग्राहकों से मिलते हैं और अपूर्ण आवश्यकताएँ, शिकायतें और सुझाव बता सकते हैं।" },
  "s12ent-b-028": { stem: "उपभोक्ताओं की जीवनशैली, मूल्यों और व्यक्तित्व के आधार पर बाज़ार को विभाजित करना कहलाता है:", options: ["भौगोलिक विभाजन", "मनोचित्रीय (साइकोग्राफ़िक) विभाजन", "जनांकिकीय विभाजन", "व्यवहारगत विभाजन"], explanation: "मनोचित्रीय विभाजन जीवनशैली, मूल्य और व्यक्तित्व का उपयोग करता है; जनांकिकीय आयु, आय आदि का; व्यवहारगत उपयोग, निष्ठा और अपेक्षित लाभ का।" },
  "s12ent-b-029": { stem: "कोई विचार वास्तविक व्यावसायिक अवसर तब बनता है जब वह:", options: ["पूर्णतः नया हो और कहीं भी आज़माया न गया हो", "उद्यमी के परिवार और मित्रों को पसंद हो", "ग्राहक की वास्तविक आवश्यकता पूरी करे, लाभ अर्जित कर सके और समय रहते उस पर कार्य हो सके", "उसमें कोई निवेश आवश्यक न हो"], explanation: "अवसर वह विचार है जो आकर्षक, टिकाऊ, समयोचित हो और खरीदारों के लिए मूल्य सृजित करे; केवल नवीनता या व्यक्तिगत पसंद पर्याप्त नहीं।" },
  "s12ent-b-030": { stem: "विचार-सृजन या पूर्वानुमान की डेल्फ़ी तकनीक में:", options: ["एक छोटा समूह संचालक के अधीन आमने-सामने विचार-विमर्श करता है", "उत्पाद के प्रत्येक गुण को सूचीबद्ध करके बदला जाता है", "विशेषज्ञों का एक पैनल कई दौरों में गुमनाम उत्तर देता है और प्रत्येक दौर के बाद सारांशित प्रतिपुष्टि दी जाती है", "ग्राहकों से विद्यमान उत्पादों की समस्याएँ सूचीबद्ध करने को कहा जाता है"], explanation: "डेल्फ़ी में समूह दबाव के बिना सुविचारित सहमति तक पहुँचने के लिए विशेषज्ञों के गुमनाम, बार-बार के उत्तर लिए जाते हैं। आमने-सामने संचालित समूह फ़ोकस समूह होते हैं।" },
  "s12ent-b-031": { stem: "एक नगर में 20,000 परिवार हैं। सर्वेक्षण बताता है कि 30% परिवार एक नया नाश्ता ब्रांड खरीदेंगे और प्रत्येक वर्ष में 4 पैकेट खरीदेगा। अनुमानित वार्षिक माँग है:", options: ["6,000 पैकेट", "24,000 पैकेट", "80,000 पैकेट", "12,000 पैकेट"], explanation: "खरीदने वाले परिवार = 20,000 का 30% = 6,000; वार्षिक माँग = 6,000 × 4 = 24,000 पैकेट।" },
  "s12ent-b-032": { stem: "अनुमानित आय विवरण, रोकड़ प्रवाह विवरण और सम-विच्छेद विश्लेषण व्यवसाय योजना के किस भाग के अंग हैं?", options: ["विपणन योजना", "संगठनात्मक योजना", "कार्यकारी सारांश", "वित्तीय योजना"], explanation: "वित्तीय योजना व्यवहार्यता दिखाने के लिए अनुमानित वित्तीय विवरण, निधि आवश्यकताएँ और सम-विच्छेद प्रस्तुत करती है।" },
  "s12ent-b-033": { stem: "उत्पाद जीवन चक्र की पतन अवस्था में फर्म सामान्यतः:", options: ["नए खरीदारों में जागरूकता हेतु भारी व्यय करती है", "ऊँचे लाभांश हेतु मलाई उतारने (स्किमिंग) की कीमत अपनाती है", "संवर्धन घटाती है, कमज़ोर रूपों को हटाती है और उत्पाद से अंतिम लाभ लेती है या उसे वापस ले लेती है", "नए विक्रय केंद्रों तक वितरण तेज़ी से बढ़ाती है"], explanation: "गिरती बिक्री और लाभ के साथ फर्में लागत घटाती हैं, उत्पाद-श्रृंखला छाँटती हैं और या तो उत्पाद से अंतिम लाभ लेती हैं या बाहर निकल जाती हैं। जागरूकता और स्किमिंग प्रवेश अवस्था के लक्षण हैं।" },
  "s12ent-b-034": { stem: "एक स्थानीय मिठाई की दुकान के लिए, उसके नगर में एक बड़ी राष्ट्रीय श्रृंखला का आना SWOT के अनुसार है:", options: ["शक्ति", "कमज़ोरी", "अवसर", "खतरा"], explanation: "यह एक बाहरी, प्रतिकूल घटना है, अतः खतरा है। शक्तियाँ और कमज़ोरियाँ आंतरिक होती हैं।" },
  "s12ent-b-035": { stem: "उद्यमी के लिए पर्यावरण अवलोकन का मुख्य उद्देश्य है:", options: ["फर्म के वार्षिक खाते तैयार करना", "कर्मचारियों का वेतन तय करना", "व्यवसाय का सरकार में पंजीकरण कराना", "बाहरी पर्यावरण में उत्पन्न होने वाले अवसरों और खतरों की पहचान करना"], explanation: "पर्यावरण अवलोकन बाहरी प्रवृत्तियों (आर्थिक, सामाजिक, तकनीकी, कानूनी आदि) पर नज़र रखता है ताकि अवसर पहचाने जा सकें और खतरों का पूर्वानुमान हो सके।" },
  "s12ent-b-036": { stem: "विचार-सृजन विधि के रूप में 'समस्या सूची विश्लेषण' में क्या किया जाता है?", options: ["उत्पाद के सभी गुण सूचीबद्ध करके प्रत्येक को बदलना", "उपभोक्ताओं को किसी उत्पाद वर्ग की समस्याओं की सूची देकर उनसे उन उत्पादों की पहचान करवाना जिनमें ये समस्याएँ हैं", "समूह द्वारा बिना आलोचना के विचार उत्पन्न करना", "विशेषज्ञों द्वारा कई दौरों में गुमनाम पूर्वानुमान"], explanation: "समस्या सूची विश्लेषण ज्ञात समस्याओं से आरंभ करके उपभोक्ताओं से उन्हें उत्पादों से जोड़ने को कहता है, जिससे भरने योग्य कमियाँ सामने आती हैं।" },
  "s12ent-p-018": { stem: "उत्पाद जीवन चक्र की अवस्थाओं का उनकी विशेषताओं से मिलान कीजिए:\nA. प्रवेश\nB. वृद्धि\nC. परिपक्वता\nD. पतन\n1. बिक्री और लाभ गिरते हैं\n2. बिक्री तेज़ी से बढ़ती है, लाभ आरंभ होता है, नए प्रतिस्पर्धी आते हैं\n3. कम बिक्री, ऊँची प्रति इकाई लागत, संभावित हानि\n4. बिक्री शिखर पर, लाभ पर दबाव, तीव्र प्रतिस्पर्धा", options: ["A-3, B-4, C-2, D-1", "A-2, B-3, C-4, D-1", "A-1, B-2, C-4, D-3", "A-3, B-2, C-4, D-1"], explanation: "प्रवेश: कम बिक्री और हानि; वृद्धि: तीव्र वृद्धि और प्रतिद्वंद्वियों का आगमन; परिपक्वता: शिखर बिक्री और तीव्र प्रतिस्पर्धा; पतन: गिरती बिक्री और लाभ।" },
  "s12ent-p-019": { stem: "अभिकथन (A): अत्यधिक नवीन, पेटेंट-संरक्षित उत्पाद आरंभ करने वाली फर्म मलाई उतारने (प्राइस स्किमिंग) की कीमत नीति अपना सकती है।\nकारण (R): नवीनता को महत्त्व देने वाले प्रारंभिक खरीदार कीमत के प्रति अपेक्षाकृत कम संवेदनशील होते हैं और पेटेंट संरक्षण तात्कालिक प्रतिस्पर्धा को सीमित करता है।", options: ["A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "स्किमिंग में नवीनता के लिए भुगतान को तैयार खरीदारों से आरंभ में ऊँची कीमत ली जाती है; प्रतिद्वंद्वी कम होने से विकास लागत शीघ्र वसूल होती है, अतः R, A की सही व्याख्या है।" },
  "s12ent-p-020": { stem: "SWOT विश्लेषण से बने TOWS मैट्रिक्स में 'WT' रणनीतियों का उद्देश्य है:", options: ["अवसरों का लाभ उठाने के लिए शक्तियों का उपयोग करना", "खतरों का सामना करने के लिए शक्तियों का उपयोग करना", "अवसरों का उपयोग करके कमज़ोरियाँ दूर करना", "कमज़ोरियाँ न्यूनतम करना और खतरों से बचना (रक्षात्मक रणनीतियाँ)"], explanation: "SO अवसरों के लिए शक्तियों का, ST खतरों के विरुद्ध शक्तियों का, WO कमज़ोरियाँ दूर करने हेतु अवसरों का उपयोग करती है, और WT रक्षात्मक है जो कमज़ोरियाँ घटाते हुए खतरों से बचती है।" },
  "s12ent-p-021": { stem: "साध्यता अध्ययन के बारे में कथनों पर विचार कीजिए:\nI. वित्तीय साध्यता अनुमानित लागत, आय, निधि के स्रोत और प्रतिफल की जाँच करती है।\nII. बाज़ार साध्यता माँग, प्रतिस्पर्धा और संभावित कीमतों की जाँच करती है।\nIII. तकनीकी साध्यता केवल फर्म की कानूनी स्थिति से संबंधित है।\nकौन-से सही हैं?", options: ["केवल I और III", "केवल II और III", "केवल I और II", "I, II और III"], explanation: "तकनीकी साध्यता तकनीक, आगत, संयंत्र और प्रक्रियाओं से संबंधित है; कानूनी आवश्यकताएँ कानूनी साध्यता में जाँची जाती हैं। अतः III गलत है।" },
  "s12ent-p-022": { stem: "व्यवसाय योजना के बारे में कौन-सा कथन सही नहीं है?", options: ["यह उद्यमी के लिए मार्गदर्शिका और वित्त जुटाने का दस्तावेज़ है", "इसमें वित्तीय अनुमानों के पीछे की मान्यताएँ बतानी चाहिए", "एक बार तैयार होने पर व्यवसाय योजना कभी संशोधित नहीं करनी चाहिए, क्योंकि निवेशक मूल आँकड़ों पर निर्भर रहते हैं", "इसमें सामान्यतः विपणन, संचालन, संगठनात्मक और वित्तीय योजनाएँ होती हैं"], explanation: "व्यवसाय योजना एक जीवंत दस्तावेज़ है जिसे परिस्थितियों और परिणामों के बदलने पर अद्यतन किया जाना चाहिए; अन्य कथन सही हैं।" },
  "s12ent-p-023": { stem: "विचार-सृजन तकनीकों का उनके विवरण से मिलान कीजिए:\nA. विचार-मंथन\nB. डेल्फ़ी तकनीक\nC. गुण सूचीकरण\nD. फ़ोकस समूह\n1. प्रतिपुष्टि सहित दौरों में विशेषज्ञों के गुमनाम उत्तर\n2. लक्षित ग्राहकों के छोटे समूह के साथ संचालित चर्चा\n3. बिना आलोचना के समूह द्वारा मुक्त विचार-सृजन\n4. उत्पाद के गुणों को सूचीबद्ध करके प्रत्येक को बदलना", options: ["A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-2, B-1, C-4, D-3", "A-3, B-1, C-4, D-2"], explanation: "विचार-मंथन: आलोचना रहित समूह सृजन; डेल्फ़ी: गुमनाम विशेषज्ञ दौर; गुण सूचीकरण: प्रत्येक गुण में परिवर्तन; फ़ोकस समूह: संचालित ग्राहक चर्चा।" },
  "s12ent-p-024": { stem: "रचनात्मक विचार-सृजन की SCAMPER जाँच-सूची में अक्षर 'E' का अर्थ है:", options: ["मूल्यांकन करना (Evaluate)", "विस्तार करना (Expand)", "अनुमान लगाना (Estimate)", "हटाना (Eliminate)"], explanation: "SCAMPER: प्रतिस्थापन (Substitute), संयोजन (Combine), अनुकूलन (Adapt), संशोधन (Modify), अन्य उपयोग (Put to another use), हटाना (Eliminate), उलटना या पुनर्व्यवस्था (Reverse/Rearrange)।" },
  "s12ent-p-025": { stem: "किसी उत्पाद का कुल बाज़ार प्रति वर्ष 5,00,000 इकाई है। एक स्टार्ट-अप इस बाज़ार के 40% (सेवा योग्य बाज़ार) की ही वास्तविक सेवा कर सकता है और पहले वर्ष में सेवा योग्य बाज़ार का 5% प्राप्त करने की आशा करता है। पहले वर्ष का बिक्री लक्ष्य है:", options: ["10,000 इकाई", "25,000 इकाई", "20,000 इकाई", "2,00,000 इकाई"], explanation: "सेवा योग्य बाज़ार = 5,00,000 का 40% = 2,00,000 इकाई; पहले वर्ष का लक्ष्य = 2,00,000 का 5% = 10,000 इकाई। 25,000 में 5% को गलती से कुल बाज़ार पर लगाया गया है।" },
  "s12ent-p-026": { stem: "निम्नलिखित में से कौन फर्म के वृहद पर्यावरण के बजाय उसके सूक्ष्म (कार्य) पर्यावरण का भाग है?", options: ["कच्चे माल के आपूर्तिकर्ता", "मुद्रास्फीति की दर", "जनसंख्या में जनांकिकीय परिवर्तन", "सरकारी नीति में परिवर्तन"], explanation: "सूक्ष्म पर्यावरण में फर्म के निकट के घटक आते हैं: आपूर्तिकर्ता, ग्राहक, प्रतिस्पर्धी और मध्यस्थ। मुद्रास्फीति, जनांकिकी और नीति वृहद शक्तियाँ हैं।" },
  "s12ent-p-027": { stem: "पर्यावरण अवलोकन की वह तकनीक जिसमें फर्म अपनी योजनाओं को परखने के लिए भविष्य के कई वैकल्पिक, संभावित चित्र बनाती है, कहलाती है:", options: ["विचार-मंथन", "गुण सूचीकरण", "परिदृश्य निर्माण (परिदृश्य नियोजन)", "सम-विच्छेद विश्लेषण"], explanation: "परिदृश्य निर्माण किसी एक पूर्वानुमान पर निर्भर रहने के बजाय फर्म को विभिन्न संभावित भविष्यों के लिए तैयार करता है।" },
  "s12ent-p-028": { stem: "एक शोधकर्ता ज़िले की सभी खुदरा दुकानों को छोटे, मध्यम और बड़े समूहों में बाँटता है और फिर प्रत्येक समूह से यादृच्छिक रूप से दुकानें चुनता है। यह प्रतिचयन विधि है:", options: ["स्तरीकृत यादृच्छिक प्रतिचयन", "सरल यादृच्छिक प्रतिचयन", "सुविधाजनक प्रतिचयन", "कोटा प्रतिचयन"], explanation: "समष्टि को समरूप स्तरों में बाँटकर प्रत्येक से यादृच्छिक प्रतिदर्श लेना स्तरीकृत यादृच्छिक प्रतिचयन है। कोटा प्रतिचयन में निश्चित संख्या गैर-यादृच्छिक रूप से पूरी की जाती है।" },
  "s12ent-p-029": { stem: "अभिकथन (A): फर्में प्रायः किसी उत्पाद में संशोधन करके या नए उपयोगकर्ता और नए उपयोग खोजकर उसकी परिपक्वता अवस्था को लंबा करने का प्रयास करती हैं।\nकारण (R): परिपक्वता अवस्था में बाज़ार में प्रतिस्पर्धियों की संख्या न्यूनतम होती है।", options: ["A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "A सत्य है: उत्पाद, बाज़ार और उपयोग में संशोधन परिपक्वता की मानक रणनीतियाँ हैं। R असत्य है: परिपक्वता में प्रतिस्पर्धा सबसे तीव्र होती है।" },
  "s12ent-p-030": { stem: "उद्यमिता में 'अवसर की खिड़की' (window of opportunity) से आशय है:", options: ["नए उत्पाद दिखाने के लिए प्रयुक्त शोरूम की खिड़की", "वह सीमित अवधि जिसमें बाज़ार बंद होने या प्रतिस्पर्धियों के आने से पहले अवसर का लाभप्रद उपयोग किया जा सकता है", "वह अवधि जिसमें बैंक ऋण ब्याज-मुक्त होता है", "ट्रेडमार्क पंजीकरण के लिए दिया गया समय"], explanation: "अवसर समयबद्ध होते हैं: बहुत जल्दी या बहुत देर से प्रवेश सफलता की संभावना घटाता है, अतः उद्यमी को खिड़की खुली रहते कार्य करना चाहिए।" },
  "s12ent-p-031": { stem: "संयंत्र का स्थान, उत्पादन प्रक्रिया, क्षमता, आपूर्तिकर्ता और माल-सूची नियंत्रण का विवरण व्यवसाय योजना के किस भाग में दिया जाता है?", options: ["विपणन योजना", "कार्यकारी सारांश", "संचालन (उत्पादन) योजना", "संगठनात्मक योजना"], explanation: "संचालन योजना बताती है कि उत्पाद कैसे बनेगा या सेवा कैसे दी जाएगी। संगठनात्मक योजना में स्वामित्व, प्रबंधन और कर्मचारी आते हैं।" },
  "s12ent-p-032": { stem: "निम्नलिखित में से कौन उद्योग विश्लेषण में प्रयुक्त माइकल पोर्टर की पाँच प्रतिस्पर्धी शक्तियों में से एक नहीं है?", options: ["नए प्रवेशकों का खतरा", "सरकारी नियमन", "आपूर्तिकर्ताओं की सौदेबाज़ी शक्ति", "स्थानापन्न उत्पादों का खतरा"], explanation: "पोर्टर की पाँच शक्तियाँ हैं: विद्यमान फर्मों में प्रतिद्वंद्विता, नए प्रवेशकों का खतरा, स्थानापन्नों का खतरा, क्रेताओं की सौदेबाज़ी शक्ति और आपूर्तिकर्ताओं की सौदेबाज़ी शक्ति। नियमन एक वृहद कारक है।" },
  "s12ent-p-033": { stem: "बाज़ार अनुसंधान में द्वितीयक आँकड़ों के बारे में कौन-सा कथन सही है?", options: ["ये सदैव प्राथमिक आँकड़ों से अधिक सटीक होते हैं", "इन्हें शोधकर्ता वर्तमान अध्ययन के लिए स्वयं पहली बार एकत्र करता है", "ये सरकारी प्रकाशनों से प्राप्त नहीं किए जा सकते", "इन्हें प्राप्त करना तेज़ और सस्ता है, परंतु ये पुराने हो सकते हैं या शोधकर्ता की समस्या के लिए विशिष्ट नहीं होते"], explanation: "द्वितीयक आँकड़े पहले से उपलब्ध होते हैं (सरकारी रिपोर्ट, पत्रिकाएँ, डेटाबेस), अतः समय और लागत बचती है, परंतु उनकी प्रासंगिकता और नवीनता जाँचनी पड़ती है।" },
  "s12ent-p-034": { stem: "उद्यमशील नियोजन प्रक्रिया का तार्किक क्रम कौन-सा है?", options: ["विचार-सृजन → विचारों की छँटाई → साध्यता अध्ययन → व्यवसाय योजना → आरंभ", "व्यवसाय योजना → विचार-सृजन → साध्यता अध्ययन → छँटाई → आरंभ", "साध्यता अध्ययन → विचार-सृजन → आरंभ → व्यवसाय योजना → छँटाई", "छँटाई → आरंभ → विचार-सृजन → व्यवसाय योजना → साध्यता अध्ययन"], explanation: "विचार उत्पन्न किए जाते हैं, छाँटे जाते हैं, सबसे आशाजनक विचार की साध्यता जाँची जाती है, फिर आरंभ से पहले विस्तृत व्यवसाय योजना बनाई जाती है।" },
  "s12ent-b-037": { stem: "व्यवसाय के ऋणों के लिए एकल स्वामी का दायित्व होता है:", options: ["असीमित, जो व्यक्तिगत संपत्ति तक फैला है", "निवेश की गई पूँजी तक सीमित", "गारंटी की गई राशि तक सीमित", "कर्मचारियों के साथ बराबर बँटा हुआ"], explanation: "एकल स्वामित्व की अलग कानूनी सत्ता नहीं होती, अतः व्यवसाय के ऋण चुकाने में स्वामी की व्यक्तिगत संपत्ति भी प्रयुक्त हो सकती है।" },
  "s12ent-b-038": { stem: "एक फर्म की स्थायी लागत ₹60,000 है। विक्रय मूल्य ₹50 प्रति इकाई और परिवर्तनशील लागत ₹30 प्रति इकाई है। इकाइयों में इसका सम-विच्छेद बिंदु है:", options: ["1,200 इकाई", "3,000 इकाई", "2,000 इकाई", "1,500 इकाई"], explanation: "प्रति इकाई अंशदान = 50 − 30 = ₹20; सम-विच्छेद बिंदु = 60,000 ÷ 20 = 3,000 इकाई। 1,200 में गलती से विक्रय मूल्य से भाग दिया गया है।" },
  "s12ent-b-039": { stem: "उद्यम पूँजी (वेंचर कैपिटल) का सर्वोत्तम वर्णन है:", options: ["उच्च जोखिम, उच्च वृद्धि वाले नए उद्यमों को दी गई इक्विटी वित्त, जिसमें सामान्यतः सार्वजनिक निर्गम या बिक्री द्वारा निकास होता है", "माल गिरवी रखकर बैंक से लिया गया अल्पकालीन ऋण", "माल की खरीद हेतु आपूर्तिकर्ताओं द्वारा दिया गया उधार", "सरकारी अनुदान जिसे लौटाना नहीं पड़ता"], explanation: "उद्यम पूँजीपति स्वामित्व हिस्सेदारी लेते हैं, प्रायः बोर्ड में भूमिका के साथ, और निश्चित ब्याज के बजाय निकास (IPO या हिस्सेदारी बिक्री) पर प्रतिफल अर्जित करते हैं।" },
  "s12ent-b-040": { stem: "एक एंजेल निवेशक सामान्यतः होता है:", options: ["एक वाणिज्यिक बैंक जो ज़मानत पर ऋण देता है", "एक धनी व्यक्ति जो प्रायः इक्विटी के बदले किसी स्टार्ट-अप में आरंभिक अवस्था में अपना निजी धन लगाता है", "एक सरकारी विभाग जो अनुदान देता है", "एक ग्राहक जो माल के लिए अग्रिम भुगतान करता है"], explanation: "एंजेल अपना धन लगाते हैं, सामान्यतः बीज या आरंभिक अवस्था में, और प्रायः मार्गदर्शन भी देते हैं। उद्यम पूँजी कोष एकत्रित धन लगाते हैं, सामान्यतः बाद की अवस्था में।" },
  "s12ent-b-041": { stem: "एक फर्म की चालू संपत्तियाँ ₹8,00,000 और चालू दायित्व ₹5,00,000 हैं। इसकी शुद्ध कार्यशील पूँजी है:", options: ["₹3,00,000", "₹13,00,000", "₹8,00,000", "₹1,60,000"], explanation: "शुद्ध कार्यशील पूँजी = चालू संपत्तियाँ − चालू दायित्व = 8,00,000 − 5,00,000 = ₹3,00,000। ₹8,00,000 सकल कार्यशील पूँजी है।" },
  "s12ent-b-042": { stem: "निम्नलिखित में से कौन ई. जेरोम मैकार्थी द्वारा दिए गए विपणन मिश्रण के मूल चार P में से एक नहीं है?", options: ["लोग (People)", "उत्पाद (Product)", "स्थान (Place)", "संवर्धन (Promotion)"], explanation: "मैकार्थी के 4 P हैं: उत्पाद, कीमत, स्थान और संवर्धन। लोग, प्रक्रिया और भौतिक साक्ष्य बाद में सेवाओं के लिए जोड़े गए (7 P)।" },
  "s12ent-b-043": { stem: "एक उत्पाद ₹80 प्रति इकाई बिकता है और इसकी परिवर्तनशील लागत ₹60 प्रति इकाई है। इसका लाभ-मात्रा (P/V) अनुपात है:", options: ["75%", "33.33%", "25%", "20%"], explanation: "P/V अनुपात = अंशदान ÷ बिक्री = (80 − 60) ÷ 80 = 20 ÷ 80 = 25%। 33.33% में गलती से अंशदान को परिवर्तनशील लागत से भाग दिया गया है।" },
  "s12ent-b-044": { stem: "भारत में सीमित दायित्व भागिता (LLP), जो LLP अधिनियम, 2008 से शासित है:", options: ["एक फर्म है जिसमें सभी साझेदारों का दायित्व असीमित होता है", "बैंक में पंजीकृत एकल स्वामित्व है", "एक पृथक कानूनी सत्ता है जिसमें साझेदारों का दायित्व सीमित होता है", "एक सदस्य, एक मत वाली सहकारी समिति है"], explanation: "LLP साझेदारी के लचीलेपन को पृथक कानूनी पहचान और साझेदारों के सीमित दायित्व के साथ जोड़ती है।" },
  "s12ent-b-045": { stem: "नई इक्विटी जारी करने के बजाय बैंक से सावधि ऋण लेकर धन जुटाने का एक प्रमुख लाभ यह है कि:", options: ["मूलधन कभी लौटाना नहीं पड़ता", "कोई ब्याज नहीं देना पड़ता", "कभी कोई प्रतिभूति या ज़मानत नहीं चाहिए", "स्वामियों का स्वामित्व और नियंत्रण कम (तनु) नहीं होता"], explanation: "ऋण ब्याज सहित लौटाना होता है और प्रायः ज़मानत चाहिए, परंतु ऋणदाता स्वामी नहीं बनते, अतः नियंत्रण उद्यमी के पास रहता है।" },
  "s12ent-b-046": { stem: "भारत में सूक्ष्म, लघु और मध्यम उद्यमों को किस अधिनियम के अंतर्गत परिभाषित और वर्गीकृत किया जाता है?", options: ["कंपनी अधिनियम, 2013", "उद्योग (विकास और विनियमन) अधिनियम, 1951", "सूक्ष्म, लघु और मध्यम उद्यम विकास (MSMED) अधिनियम, 2006", "कारखाना अधिनियम, 1948"], explanation: "MSMED अधिनियम, 2006 MSME के वर्गीकरण का कानूनी ढाँचा देता है; सीमाएँ अधिनियम की धारा 7 के अंतर्गत केंद्र सरकार द्वारा अधिसूचित की जाती हैं।" },
  "s12ent-b-047": { stem: "एन्सॉफ़ मैट्रिक्स में, आक्रामक कीमत और संवर्धन द्वारा विद्यमान बाज़ारों में विद्यमान उत्पादों की बिक्री बढ़ाना कहलाता है:", options: ["बाज़ार विकास", "उत्पाद विकास", "विविधीकरण", "बाज़ार प्रवेशन"], explanation: "बाज़ार प्रवेशन = विद्यमान उत्पाद, विद्यमान बाज़ार। बाज़ार विकास विद्यमान उत्पादों को नए बाज़ारों तक ले जाता है; उत्पाद विकास विद्यमान बाज़ारों को नए उत्पाद देता है।" },
  "s12ent-b-048": { stem: "फ्रेंचाइज़िंग व्यवस्था में, वह पक्ष जो शुल्क और रॉयल्टी के बदले अपने ब्रांड नाम, उत्पादों और व्यावसायिक प्रणाली के उपयोग का अधिकार देता है:", options: ["फ्रेंचाइज़ी (अधिकार लेने वाला)", "वितरक", "अनुज्ञप्तिधारी", "फ्रेंचाइज़र (अधिकार देने वाला)"], explanation: "फ्रेंचाइज़र ब्रांड और प्रणाली का स्वामी होता है; फ्रेंचाइज़ी उसके अंतर्गत कार्य करने के अधिकार के लिए भुगतान करता है।" },
  "s12ent-b-049": { stem: "एक फर्म कच्चा माल और तैयार माल 60 दिन तक रखती है, ग्राहकों को 45 दिन का उधार देती है और आपूर्तिकर्ताओं से 30 दिन का उधार पाती है। इसका शुद्ध परिचालन (रोकड़ रूपांतरण) चक्र है:", options: ["135 दिन", "105 दिन", "75 दिन", "15 दिन"], explanation: "शुद्ध परिचालन चक्र = माल-सूची अवधि + प्राप्य अवधि − देय अवधि = 60 + 45 − 30 = 75 दिन। 105 दिन सकल परिचालन चक्र है।" },
  "s12ent-b-050": { stem: "संस्थापक की निजी बचत और फर्म की अपनी आरंभिक आय से, बिना बाहरी निवेशकों के, व्यवसाय आरंभ करना और बढ़ाना कहलाता है:", options: ["क्राउडफंडिंग (जन-वित्तपोषण)", "बूटस्ट्रैपिंग (स्व-वित्तपोषण)", "उद्यम वित्तपोषण", "पट्टेदारी (लीज़िंग)"], explanation: "बूटस्ट्रैपिंग आंतरिक निधि और कड़े लागत नियंत्रण पर निर्भर है। क्राउडफंडिंग में प्रायः ऑनलाइन अनेक लोगों से छोटी राशियाँ जुटाई जाती हैं।" },
  "s12ent-b-051": { stem: "विपणन मिश्रण का 'स्थान' (Place) तत्व किससे संबंधित है?", options: ["वितरण माध्यम, विक्रय केंद्र का स्थान, परिवहन और उत्पाद की उपलब्धता", "उत्पाद का पैकेजिंग और ब्रांड नाम", "विज्ञापन और विक्रय संवर्धन", "दी जाने वाली छूट और उधार की शर्तें"], explanation: "स्थान (वितरण) सुनिश्चित करता है कि उत्पाद वहाँ और तब उपलब्ध हो जहाँ और जब ग्राहक चाहें। पैकेजिंग उत्पाद, विज्ञापन संवर्धन और छूट कीमत के अंतर्गत आते हैं।" },
  "s12ent-p-035": { stem: "एक फर्म की स्थायी लागत ₹1,20,000 है और इसका P/V अनुपात 40% है। इसकी सम-विच्छेद बिक्री है:", options: ["₹48,000", "₹3,00,000", "₹2,00,000", "₹1,68,000"], explanation: "सम-विच्छेद बिक्री = स्थायी लागत ÷ P/V अनुपात = 1,20,000 ÷ 0.40 = ₹3,00,000। ₹2,00,000 में गलती से 60% (परिवर्तनशील लागत अनुपात) से भाग दिया गया है।" },
  "s12ent-p-036": { stem: "एक फर्म की बिक्री ₹5,00,000, परिवर्तनशील लागत ₹3,00,000 और स्थायी लागत ₹1,50,000 है। इसकी सुरक्षा सीमा है:", options: ["₹50,000", "₹1,25,000", "₹3,75,000", "₹2,00,000"], explanation: "P/V अनुपात = 2,00,000 ÷ 5,00,000 = 40%; सम-विच्छेद बिक्री = 1,50,000 ÷ 0.40 = ₹3,75,000; सुरक्षा सीमा = 5,00,000 − 3,75,000 = ₹1,25,000। जाँच: लाभ = 1,25,000 × 40% = ₹50,000 = 2,00,000 − 1,50,000।" },
  "s12ent-p-037": { stem: "स्थायी लागत ₹40,000, विक्रय मूल्य ₹20 प्रति इकाई और परिवर्तनशील लागत ₹12 प्रति इकाई है। ₹24,000 का लाभ कमाने के लिए कितनी इकाइयाँ बेचनी होंगी?", options: ["8,000 इकाई", "5,000 इकाई", "3,000 इकाई", "3,200 इकाई"], explanation: "आवश्यक इकाइयाँ = (स्थायी लागत + लक्षित लाभ) ÷ प्रति इकाई अंशदान = (40,000 + 24,000) ÷ 8 = 8,000 इकाई। 5,000 इकाई केवल सम-विच्छेद बिंदु है।" },
  "s12ent-p-038": { stem: "एक फर्म एक अवधि में ₹3,00,000 की बिक्री पर ₹30,000 का लाभ और अगली अवधि में ₹4,00,000 की बिक्री पर ₹60,000 का लाभ दर्शाती है; कीमत या लागत संरचना में कोई परिवर्तन नहीं है। इसकी सम-विच्छेद बिक्री है:", options: ["₹2,00,000", "₹1,00,000", "₹1,50,000", "₹2,50,000"], explanation: "P/V अनुपात = लाभ में परिवर्तन ÷ बिक्री में परिवर्तन = 30,000 ÷ 1,00,000 = 30%। स्थायी लागत = 3,00,000 का 30% − 30,000 = ₹60,000। सम-विच्छेद बिक्री = 60,000 ÷ 0.30 = ₹2,00,000।" },
  "s12ent-p-039": { stem: "स्थायी लागत ₹90,000, विक्रय मूल्य ₹60 प्रति इकाई और परिवर्तनशील लागत ₹45 प्रति इकाई है। लागत अपरिवर्तित रहते हुए विक्रय मूल्य ₹63 कर दिया जाए, तो नया सम-विच्छेद बिंदु है:", options: ["6,000 इकाई", "5,500 इकाई", "5,000 इकाई", "4,500 इकाई"], explanation: "मूल सम-विच्छेद बिंदु = 90,000 ÷ 15 = 6,000 इकाई। नया अंशदान = 63 − 45 = ₹18, अतः नया सम-विच्छेद बिंदु = 90,000 ÷ 18 = 5,000 इकाई।" },
  "s12ent-p-040": { stem: "एक फर्म की चालू संपत्तियाँ ₹6,00,000 हैं, जिनमें ₹2,00,000 की माल-सूची शामिल है, और चालू दायित्व ₹4,00,000 हैं। इसका चालू अनुपात और त्वरित (तरल) अनुपात क्रमशः हैं:", options: ["1.5 : 1 और 1 : 1", "1 : 1 और 1.5 : 1", "2 : 1 और 1 : 1", "1.5 : 1 और 0.5 : 1"], explanation: "चालू अनुपात = 6,00,000 ÷ 4,00,000 = 1.5 : 1। त्वरित संपत्तियाँ = 6,00,000 − 2,00,000 = 4,00,000, अतः त्वरित अनुपात = 4,00,000 ÷ 4,00,000 = 1 : 1।" },
  "s12ent-p-041": { stem: "MSMED अधिनियम, 2006 के अंतर्गत, 1 जुलाई 2020 से प्रभावी अधिसूचना द्वारा संशोधित MSME वर्गीकरण मानदंडों पर विचार कीजिए:\nI. उद्यमों का वर्गीकरण संयंत्र और मशीनरी या उपकरण में निवेश तथा वार्षिक टर्नओवर के संयुक्त मानदंड पर होता है।\nII. विनिर्माण और सेवा उद्यमों के अलग-अलग मानदंडों के स्थान पर समान मानदंड लागू किए गए।\nIII. उद्यमों का वर्गीकरण नियोजित श्रमिकों की संख्या के आधार पर होता है।\nकौन-से सही हैं?", options: ["केवल I और II", "केवल I और III", "केवल II और III", "I, II और III"], explanation: "2020 के संशोधन ने निवेश और टर्नओवर का संयुक्त मानदंड लागू किया और विनिर्माण/सेवा का भेद समाप्त किया। कर्मचारियों की संख्या मानदंड नहीं है।" },
  "s12ent-p-042": { stem: "अभिकथन (A): संशोधित MSME वर्गीकरण मानदंडों (1 जुलाई 2020 से प्रभावी) के अंतर्गत, उद्यम के टर्नओवर की गणना में निर्यात से प्राप्त टर्नओवर शामिल नहीं किया जाता।\nकारण (R): इस अपवर्जन का उद्देश्य यह सुनिश्चित करना है कि MSME दर्जा खोने के भय से उद्यम निर्यात करने से हतोत्साहित न हों।", options: ["A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "निर्यात को बाहर रखने से MSME टर्नओवर सीमा पार किए बिना निर्यात बढ़ा सकता है, जो इस नियम की सीधी व्याख्या है।" },
  "s12ent-p-043": { stem: "निम्नलिखित में से कौन-सा फर्म की कार्यशील पूँजी की आवश्यकता को बढ़ाएगा?", options: ["उत्पादन चक्र को छोटा करना", "ग्राहकों को अधिक उदार उधार शर्तें देना", "आपूर्तिकर्ताओं से लंबी उधार अवधि प्राप्त करना", "पूर्णतः नकद बिक्री अपनाना"], explanation: "ग्राहकों को लंबा उधार देने से प्राप्य बढ़ते हैं और परिचालन चक्र लंबा होता है, अतः अधिक धन फँसता है। अन्य परिवर्तन चक्र छोटा करते हैं या चालू संपत्तियाँ घटाते हैं।" },
  "s12ent-p-044": { stem: "कथनों पर विचार कीजिए:\nI. एंजेल निवेशक सामान्यतः उद्यम पूँजी कोषों की अपेक्षा पहले की अवस्था में अपना धन लगाते हैं।\nII. उद्यम पूँजी कोष संस्थाओं और अन्य निवेशकों से एकत्रित धन का निवेश करते हैं।\nIII. दोनों सामान्यतः सार्वजनिक निर्गम या हिस्सेदारी की बिक्री द्वारा निकास चाहते हैं।\nIV. उद्यम पूँजी निश्चित ब्याज दर वाला ऋण साधन है।\nकौन-से सही हैं?", options: ["केवल I और II", "केवल II और IV", "केवल I, II और III", "केवल I, III और IV"], explanation: "उद्यम पूँजी मुख्यतः इक्विटी (या इक्विटी से जुड़ा) वित्त है, निश्चित ब्याज वाला ऋण नहीं, अतः IV गलत है; I, II और III सही हैं।" },
  "s12ent-p-045": { stem: "एन्सॉफ़ वृद्धि रणनीतियों का उनके विवरण से मिलान कीजिए:\nA. बाज़ार विकास\nB. उत्पाद विकास\nC. विविधीकरण\nD. बाज़ार प्रवेशन\n1. नए बाज़ार में नया उत्पाद\n2. नए बाज़ारों में विद्यमान उत्पाद\n3. विद्यमान बाज़ार के लिए नया उत्पाद\n4. विद्यमान बाज़ार में विद्यमान उत्पाद की अधिक हिस्सेदारी", options: ["A-2, B-3, C-1, D-4", "A-3, B-2, C-1, D-4", "A-2, B-3, C-4, D-1", "A-1, B-3, C-2, D-4"], explanation: "बाज़ार विकास: विद्यमान उत्पाद, नया बाज़ार; उत्पाद विकास: नया उत्पाद, विद्यमान बाज़ार; विविधीकरण: नया उत्पाद, नया बाज़ार; प्रवेशन: विद्यमान उत्पाद, विद्यमान बाज़ार।" },
  "s12ent-p-046": { stem: "एक वस्त्र (गारमेंट) निर्माता उसे कपड़ा आपूर्ति करने वाली एक कपड़ा मिल का अधिग्रहण करता है। यह वृद्धि रणनीति किसका उदाहरण है?", options: ["पश्चगामी ऊर्ध्वाधर एकीकरण", "अग्रगामी ऊर्ध्वाधर एकीकरण", "क्षैतिज एकीकरण", "समूह (कांग्लोमरेट) विविधीकरण"], explanation: "आगत आपूर्तिकर्ता का अधिग्रहण फर्म को आपूर्ति श्रृंखला में पीछे की ओर ले जाता है। खुदरा विक्रेता का अधिग्रहण अग्रगामी और प्रतिद्वंद्वी गारमेंट निर्माता का अधिग्रहण क्षैतिज एकीकरण होता।" },
  "s12ent-p-047": { stem: "संयुक्त हिंदू परिवार (HUF) व्यवसाय में सदस्यों का दायित्व होता है:", options: ["कर्ता का असीमित, और अन्य सहभागियों (सह-उत्तराधिकारियों) का संयुक्त पारिवारिक संपत्ति में उनके हिस्से तक सीमित", "सभी सदस्यों का समान रूप से असीमित", "कर्ता सहित सभी सदस्यों का सीमित", "सहभागियों का असीमित और कर्ता का सीमित"], explanation: "कर्ता व्यवसाय का प्रबंधन करता है और असीमित दायित्व वहन करता है; अन्य सहभागी केवल पारिवारिक संपत्ति में अपने हिस्से तक उत्तरदायी होते हैं।" },
  "s12ent-p-048": { stem: "एक इकाई की स्थायी लागत ₹50,000 प्रति माह और परिवर्तनशील लागत ₹25 प्रति इकाई है। यदि मासिक उत्पादन 2,000 से बढ़कर 2,500 इकाई हो जाए, तो प्रति इकाई औसत (कुल) लागत होगी:", options: ["₹50", "₹40", "₹45", "₹20"], explanation: "2,500 इकाई पर: प्रति इकाई स्थायी लागत = 50,000 ÷ 2,500 = ₹20; औसत लागत = 25 + 20 = ₹45। 2,000 इकाई पर यह 25 + 25 = ₹50 थी, अतः स्थायी लागत के फैलाव से इकाई लागत घटती है।" },
  "s12ent-p-049": { stem: "एक फर्म की बेचे गए माल की लागत ₹6,00,000 है। इसकी आरंभिक माल-सूची ₹1,00,000 और अंतिम माल-सूची ₹2,00,000 है। 360 दिन का वर्ष मानने पर, इसकी माल-सूची रूपांतरण अवधि है:", options: ["60 दिन", "90 दिन", "120 दिन", "45 दिन"], explanation: "औसत माल-सूची = (1,00,000 + 2,00,000) ÷ 2 = ₹1,50,000; माल-सूची आवर्त = 6,00,000 ÷ 1,50,000 = 4 बार; रूपांतरण अवधि = 360 ÷ 4 = 90 दिन।" },
};
